text:
{
  "status": "ready",
  "questions": [],
  "reason": "사용자의 '게임 업계 실무 문제 분석' 요청에 따라 중급 난이도의 플레이어 이탈 및 전투 콘텐츠 실패율 분석 과제를 설계했습니다.",
  "topic": "게임 플레이어 이탈 원인 및 전투 실패율 분석",
  "goal": "특정 전투 스테이지의 난이도 급상승에 따른 유저 이탈 패턴을 분석하고 개선 의사결정을 내린다.",
  "title": "모바일 RPG 보스 스테이지 실패율과 유저 이탈 관계 분석",
  "description": "본 과제는 모바일 RPG 게임에서 신규 보스 스테이지 도입 전후의 플레이어 실패율, 재도전 횟수, 그리고 최종 이탈 여부 간의 상관관계를 분석하는 실무형 과제입니다. 학습자는 제공된 플레이어 프로필과 전투 로그를 결합하여 특정 구간에서 발생하는 병목 현상을 파악하고, 난이도 조정을 위한 데이터 기반의 인사이트를 도출해야 합니다.",
  "difficulty": "intermediate",
  "difficulty_reason": "중급 난이도로 설정하여 단순 집계를 넘어 프로필 그룹별 비교, 실패율과 이탈 간의 상관관계 해석, 그리고 대안 검토 과정을 포함했습니다.",
  "task_kind": "investigation",
  "completion_conditions": [
    "플레이어 그룹별 평균 전투 실패 횟수 및 이탈률 산출 완료",
    "특정 보스 스테이지에서의 재도전 지연 시간과 이탈 간의 관계 설명",
    "난이도 조정을 위한 구체적인 액션 플랜 제시"
  ],
  "limitations": [
    "제공된 가상 데이터 범위 내에서만 분석을 수행합니다.",
    "실제 외부 서버 로그나 외부 경제 지표는 고려하지 않습니다."
  ],
  "tables": [
    {
      "name": "players",
      "grain": "계정별 1행",
      "columns": [
        {
          "name": "id",
          "description": "계정 고유 식별자",
          "generator": {
            "kind": "id"
          }
        },
        {
          "name": "tier",
          "description": "플레이어 티어 등급",
          "generator": {
            "kind": "category",
            "values": ["bronze", "silver", "gold"]
          }
        },
        {
          "name": "joined_at",
          "description": "계정 생성 시각",
          "generator": {
            "kind": "timestamp",
            "start": "2026-09-01T00:00:00+09:00",
            "end": "2026-09-05T00:00:00+09:00"
          }
        }
      ],
      "groups": [
        {
          "name": "sample",
          "count": 200
        }
      ],
      "unique_keys": [
        ["id"]
      ]
    },
    {
      "name": "battles",
      "grain": "전투 시도별 1행",
      "columns": [
        {
          "name": "id",
          "description": "전투 로그 고유 식별자",
          "generator": {
            "kind": "id"
          }
        },
        {
          "name": "account_id",
          "description": "플레이어 계정 ID",
          "generator": {
            "kind": "foreign_key",
            "table": "players",
            "group": "sample"
          }
        },
        {
          "name": "wait_seconds",
          "description": "전투 전 대기 시간",
          "generator": {
            "kind": "integer",
            "minimum": 5,
            "maximum": 60
          }
        },
        {
          "name": "duration_seconds",
          "description": "전투 소요 시간",
          "generator": {
            "kind": "integer",
            "minimum": 30,
            "maximum": 300
          }
        },
        {
          "name": "started_at",
          "description": "전투 시작 시각",
          "generator": {
            "kind": "timestamp_sequence",
            "entity_column": "account_id",
            "interval_column": "wait_seconds",
            "duration_column": "duration_seconds",
            "partition_columns": [],
            "operation": null,
            "conditions": [],
            "value_type": null,
            "bucket": null,
            "timezone": "Asia/Seoul"
          }
        },
        {
          "name": "ended_at",
          "description": "전투 종료 시각",
          "generator": {
            "kind": "timestamp_offset",
            "source_column": "started_at",
            "timezone": "Asia/Seoul"
          }
        },
        {
          "name": "success",
          "description": "전투 성공 여부 (1: 성공, 0: 실패)",
          "generator": {
            "kind": "integer",
            "minimum": 0,
            "maximum": 1
          }
        }
      ],
      "groups": [
        {
          "name": "sample",
          "count": 400
        }
      ],
      "unique_keys": [
        ["id"]
      ]
    }
  ],
  "metrics": [
    {
      "name": "total_battles",
      "table": "battles",
      "operation": "count",
      "purpose": "validation"
    },
    {
      "name": "success_rate_by_tier",
      "table": "battles",
      "operation": "ratio",
      "conditions": [
        {
          "column": "success",
          "operator": "eq",
          "value": 1
        }
      ],
      "purpose": "analysis",
      "joins": [
        {
          "table": "players",
          "source_column": "account_id"
        }
      ],
      "group_by": [
        "players.tier"
      ]
    }
  ],
  "business_case": {
    "provenance": "synthetic",
    "background": "라이브 서비스 중인 모바일 RPG에서 특정 보스 스테이지 도입 이후 유저들의 불만이 증가하고 있어 라이브오퍼레이션 팀에서 원인 분석에 착수했습니다.",
    "observed_problem": "실버 티어 유저들의 전투 실패율이 급증하고 있으며, 이로 인한 일일 접속 중단 비율이 평소 대비 높게 관측되고 있습니다.",
    "observation_period": "2026-09-01부터 2026-09-10까지",
    "decision": "분석 결과를 바탕으로 해당 보스의 체력 및 패턴 난이도를 하향 조정하거나 가이드를 보강할지 결정합니다.",
    "agent_assumptions": [
      "모든 플레이어는 공정하게 무작위 배정된 샘플 데이터에 속합니다.",
      "전투 성공 여부는 로그 내 success 컬럼(1 또는 0)으로 명확히 기록됩니다."
    ],
    "requirements": [
      {
        "competency": "measurement",
        "question": "전체 플레이어의 티어별 총 전투 횟수와 전투 성공률은 각각 얼마인가요?",
        "evidence": [
          {
            "table": "battles",
            "columns": ["id", "success"]
          },
          {
            "table": "players",
            "columns": ["id", "tier"]
          }
        ],
        "completion": "티어별 전체 전투 횟수와 성공률 지표를 정확히 산출해야 합니다."
      },
      {
        "competency": "comparison",
        "question": "브론즈 티어와 실버 티어 간의 전투 소요 시간 및 성공률 차이를 비교하고, 어느 구간에서 실패가 집중되는지 설명하세요.",
        "evidence": [
          {
            "table": "battles",
            "columns": ["duration_seconds", "success"]
          },
          {
            "table": "players",
            "columns": ["tier"]
          }
        ],
        "completion": "두 티어 간의 성공률과 전투 시간을 비교하여 차이점을 도출해야 합니다."
      },
      {
        "competency": "decision",
        "question": "분석된 실패율 데이터를 근거로 난이도 조정이 가장 시급한 타겟 그룹과 우선순위 조치 방안을 제시하세요.",
        "evidence": [
          {
            "table": "battles",
            "columns": ["success", "duration_seconds"]
          }
        ],
        "completion": "근거 데이터를 기반으로 한 타겟 그룹 선정 및 구체적인 의사결정 방안을 작성해야 합니다."
      }
    ]
  },
  "rubric": "정확한 지표 산출과 논리적인 티어별 비교, 그리고 데이터에 기반한 의사결정 제안이 포함되었는지 평가합니다.",
  "labels_public": false
}
